TEE_Result setup_mem_region(const struct optee_msg_param_rmem *rmem,
                            struct param_mem *mem)
{
    struct TEE_SharedMemory *shm = NULL;

    if (!rmem || !mem)
        return TEE_ERROR_BAD_PARAMETERS;

    shm = TEE_GetSharedMemoryByRef(rmem->shm_ref);
    if (!shm)
        return TEE_ERROR_ITEM_NOT_FOUND;

    if (rmem->offset + rmem->size > shm->size) {
        TEE_ReleaseSharedMemory(shm);
        return TEE_ERROR_BAD_RANGE;
    }

    mem->buffer = (uint8_t *)shm->buffer + rmem->offset;
    mem->size = rmem->size;

    TEE_ReleaseSharedMemory(shm);
    return TEE_SUCCESS;
}

