TEE_Result set_mem_parameters(const struct optee_msg_param_rmem *rmem,
                              struct param_mem *mem) {
    void *shm;
    TEE_Result res;

    shm = TEE_GetSharedMemoryByReference(&rmem->reference);
    if (!shm)
        return TEE_ERROR_ITEM_NOT_FOUND;

    if (rmem->offset + rmem->size > TEE_GetSharedMemorySize(shm))
        return TEE_ERROR_BAD_SIZE;

    mem->buffer = (uint8_t *)TEE_GetSharedMemoryPtr(shm) + rmem->offset;
